// Example: pseudo-configure per-language variants and canary rollout
const variants = [
  { Language: 'en', VariantName: 'prod-en', ModelName: 'sentiment-en', TrafficSplit: 0.8 },
  { Language: 'en', VariantName: 'canary-en', ModelName: 'sentiment-en-v2', TrafficSplit: 0.2 }
  // ...additional languages
];
